package unverified;

import metadata.BehavioralDifference;
import metadata.DifferenceType;

import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static unverified.ClonePairGenericInvocationTestSupport.*;

@Tag("timeout")
class ClonePair12296DifferenceFindingTest {

    private final ClonePair12296 subject = new ClonePair12296();

    /**
     * Generated by Claude Code (Claude Fable 5.1).
     * Difference type: no_termination.
     * Difference manifestation: the methods differ in whether they terminate.
     */
    @Test
    @BehavioralDifference(DifferenceType.NO_TERMINATION)
    void methodsDisagreeOnTermination() {
        InvocationOutcome method1Outcome = captureWithTimeout(values -> subject.method1(((Long) values[0]).longValue(), ((Long) values[1]).longValue()), 200L, 0L, -3L);
        InvocationOutcome method2Outcome = captureWithTimeout(values -> subject.method2(((Long) values[0]).longValue(), ((Long) values[1]).longValue()), 200L, 0L, -3L);

        assertEquals("OK", method1Outcome.status);
        assertEquals("TIMEOUT", method2Outcome.status);
    }
}
